function initCar(){const hov=()=>matchMedia('(hover:hover)').matches;
$$('.car').forEach(car=>{const tr=car.querySelector('.vtrack');let vx=0,raf=0;
tr.querySelectorAll('.vcard').forEach(c=>{const v=c.querySelector('video'),m=c.querySelector('.vm');
const play=()=>{$$('.vcard video').forEach(o=>{if(o!==v)o.pause()});$$('.vcard.act').forEach(o=>{if(o!==c)o.classList.remove('act')});c.classList.add('act');const p=v.play();if(p&&p.catch)p.catch(()=>{})},pause=()=>{c.classList.remove('act');v.pause()};
c.addEventListener('mouseenter',()=>{if(hov())play()});c.addEventListener('mouseleave',()=>{if(hov())pause()});
c.addEventListener('click',e=>{if(!hov()&&e.target!==m)v.paused?play():pause()});
c.addEventListener('focus',play);c.addEventListener('blur',pause);
m.onclick=e=>{e.stopPropagation();v.muted=!v.muted;m.textContent=v.muted?'🔇':'🔊'}});
const step=()=>{if(vx)tr.scrollLeft+=vx;raf=vx?requestAnimationFrame(step):0};
car.addEventListener('mousemove',e=>{const r=car.getBoundingClientRect(),x=e.clientX-r.left,z=Math.max(90,r.width*.2);vx=x<z?-(1-x/z)*16:x>r.width-z?(1-(r.width-x)/z)*16:0;if(vx&&!raf)raf=requestAnimationFrame(step)});
car.addEventListener('mouseleave',()=>{vx=0});
car.querySelector('.cb.l').onclick=()=>tr.scrollBy({left:-320,behavior:'smooth'});car.querySelector('.cb.r').onclick=()=>tr.scrollBy({left:320,behavior:'smooth'})})}



