QZ['h2p']=[['فلاج بيوقف رسايل التقدّم في cURL؟','-s','-v','-O'],['فلاج بيحفظ الرد باسم ملف تختاره إنت؟','-o','-O','-h']];
QZ['h3p']=[['فلاج بيتجاوز فحص شهادة SSL في cURL؟','-k','-s','-i'],['إيه اللي بيحمي البيانات من الـ Sniffing؟','التشفير بعد TLS Handshake','اسم الدومين نفسه','رقم البورت']];
QZ['h4p']=[['ترتيب السطر الأول في أي HTTP Request؟','Method ثم Path ثم Version','Version ثم Method ثم Path','Path ثم Version ثم Method'],['فين مكان الـ Body في الطلب؟','بعد سطر فاضي يقفل الهيدرز','قبل السطر الأول','جوه الـ Host header']];
QZ['h5p']=[['فلاج cURL بيطبع الطلب والرد كاملين؟','-v','-s','-O'],['فلاج بيعمل HEAD request ويطبع هيدرز الرد بس؟','-I','-i','-d']];
