/* ---------- فلاج Dynamic: كل جهاز/متصفح ليه Instance وفلاج مختلف، وبيتجدد لوحده بعد 30 دقيقة ---------- */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function randToken(rng,len){const ch='abcdefghijklmnopqrstuvwxyz0123456789';let s='';for(let i=0;i<len;i++)s+=ch[Math.floor(rng()*ch.length)];return s}
function fragsFromSeed(seed){const rng=mulberry32(seed);return[randToken(rng,6),randToken(rng,6),randToken(rng,6),randToken(rng,6)]}
function ctfKey(mid){return 'ctf_'+mid}
function ctfSolved(mid){return !!(P[ctfKey(mid)]&&P[ctfKey(mid)].solved)}
function instanceFlag(mid){const st=P[ctfKey(mid)];if(!st||!st.seed)return '';const f=fragsFromSeed(st.seed);return '0xWR{'+f.join('_')+'}'}
function shareText(){return 'حليت تحدي 🚩 Breach The Vault في موديول Web Requests Fundamentals على موقعي الشخصي! جرّب تتحدّى نفسك كمان: https://0xwo1vreen.github.io/'}
function shareUrl(p){const text=encodeURIComponent(shareText()),url=encodeURIComponent('https://0xwo1vreen.github.io/');
if(p==='whatsapp')return 'https://wa.me/?text='+text;
if(p==='x')return 'https://twitter.com/intent/tweet?text='+text;
if(p==='linkedin')return 'https://www.linkedin.com/sharing/share-offsite/?url='+url;
return '#'}

/* ---------- السيرفر الوهمي: المسارات والفلاجات مبنية من فلاج الجهاز الحالي، بدون أي تلميح مباشر لإيه اللي بعده ---------- */
let CF=['','','',''];
function labParse(line){
const kflag=/(^|\s)-k(\s|$)/.test(line);
const ihead=/(^|\s)-I(\s|$)/i.test(line)||/(^|\s)-i(\s|$)/.test(line);
const xm=line.match(/-X\s+(\w+)/i);
const method=(xm?xm[1]:'GET').toUpperCase();
const scheme=/https:\/\//i.test(line)?'https':'http';
let path='/';
const um=line.match(/https?:\/\/[^\/\s]+(\/[^\s]*)?/i);
if(um&&um[1])path=um[1];else{const pm=line.match(/(^|\s)(\/[^\s]*)/);if(pm)path=pm[2]}
path=path.replace(/[?#].*$/,'').replace(/\/+$/,'')||'/';
return{method,scheme,path:path.toLowerCase(),kflag,ihead}}

function labRun(lineRaw){const line=(lineRaw||'').trim();if(!line)return '';
if(/^help$/i.test(line))return 'curl [-k] [-I|-i] [-X METHOD] <url>\nclear   — نضّف الشاشة';
if(/^clear$/i.test(line))return '__CLEAR__';
if(!/^curl\b/i.test(line))return 'bash: '+line.split(/\s+/)[0]+': command not found';
const{method,scheme,path,kflag,ihead}=labParse(line);
const p1='/ops-'+CF[0],p2='/svc/registry-'+CF[2];

if(path==='/'||path===''){
return 'HTTP/1.1 200 OK\nContent-Type: text/html\n\n<html><body><h1>Vault Corp — Internal Portal</h1><p>Authorized access only.</p></body></html>'}

if(path==='/robots.txt'){
return 'HTTP/1.1 200 OK\nContent-Type: text/plain\n\nUser-agent: *\nDisallow: '+p1}

if(path===p1){
if(scheme==='http')return 'HTTP/1.1 400 Bad Request\nContent-Type: application/json\n\n{"error":"plaintext channel rejected"}';
if(!kflag)return 'curl: (60) SSL certificate problem: unable to get local issuer certificate\nMore details here: https://curl.se/docs/sslcerts.html';
if(ihead)return 'HTTP/1.1 200 OK\nServer: nginx\nSet-Cookie: session=7f0c2a; HttpOnly\nX-Request-Id: 9b31-44fa-aa02\nFlag-2: '+CF[1]+'\nLink: <'+p2+'>; rel="related"\nContent-Type: application/json\n\n{"area":"ops-console"}';
return 'HTTP/1.1 200 OK\nContent-Type: application/json\n\n{"area":"ops-console","flag 1":"'+CF[0]+'"}'}

if(path===p2){
if(scheme!=='https'||!kflag)return 'curl: (60) SSL certificate problem: unable to get local issuer certificate';
if(method==='DELETE')return 'HTTP/1.1 403 Forbidden\nContent-Type: application/json\n\n{"error":"insufficient privileges"}';
if(method==='OPTIONS')return 'HTTP/1.1 204 No Content\nAllow: GET, DELETE';
return 'HTTP/1.1 200 OK\nContent-Type: application/json\n\n{"service":"registry","status":"confidential","flag 3":"'+CF[2]+'","flag 4":"'+CF[3]+'"}'}

return 'HTTP/1.1 404 Not Found\nContent-Type: text/plain\n\nNothing here.'}

function htmlesc(s){return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function labInit(){const out=$('#labout'),inp=$('#labin');if(!out||!inp)return;
const pr=html=>{const d=document.createElement('div');d.className='labline';d.innerHTML=html;out.appendChild(d);out.scrollTop=out.scrollHeight};
inp.onkeydown=e=>{if(e.key!=='Enter')return;const v=inp.value;inp.value='';if(!v.trim())return;
pr('<span class="labp">$</span> '+htmlesc(v));
const r=labRun(v);
if(r==='__CLEAR__'){out.innerHTML='';return}
if(r)pr('<pre>'+htmlesc(r)+'</pre>')};
out.addEventListener('mouseup',()=>{setTimeout(()=>{if(!(window.getSelection()+'').trim())inp.focus()},0)});
inp.focus()}

/* ---------- بطاقة العرض (شكل منصات CTF) ---------- */
function fmtMMSS(ms){const s=Math.max(0,Math.ceil(ms/1000)),m=Math.floor(s/60),r=s%60;return (m<10?'0':'')+m+':'+(r<10?'0':'')+r}

function ctfHTML(mid,CH){const solved=ctfSolved(mid);
return '<div class="chall">'
+'<div class="chtop"><span class="chtag cat">'+esc(CH.cat)+'</span><span class="chtag diff">'+esc(CH.diff)+'</span>'+(solved?'<span class="chtag done">✓ Solved</span>':'')+'</div>'
+'<h2 class="chtitle">'+esc(CH.title)+'</h2>'
+'<div class="chby">by '+esc(CH.by)+' · '+esc(CH.mod)+'</div>'
+'<p class="chdesc">'+esc(CH.desc)+'</p>'
+'<h3 class="chsec">Instance</h3>'
+'<div class="chinst"><button id="launchBtn" class="go">Launch Instance</button><button id="restartBtn" class="go2" style="display:none">⟲ Restart Instance</button><small id="launchHelp">تفاصيل الهدف هتظهر بعد ما تشغّل الـ Instance.</small>'+(solved?'':'<span class="chtimer" id="chtimer" style="display:none"></span>')+'</div>'
+(solved?'':'<div class="note sm">الفلاج مُولَّد خصيصًالجهازك دلوقتي، ومش هيشتغل لو جالك من حد تاني. كمان بيتجدد تلقائيًا كل '+CH.mins+' دقيقة.</div>')
+'<div id="labArea" style="display:none"><div class="labwrap"><div class="labhead">💻 Lab Terminal — <span dir="ltr">'+esc(CH.target)+'</span></div><div class="labout" id="labout"></div><div class="labrow"><span class="labp">$</span><input id="labin" class="labin" dir="ltr" autocomplete="off" spellcheck="false" placeholder="curl ..."></div></div></div>'
+'<h3 class="chsec">Hints</h3>'
+'<ol class="chhints">'+CH.hints.map(h=>'<li>'+esc(h)+'</li>').join('')+'</ol>'
+'<h3 class="chsec">Flag</h3>'
+'<div class="row c"><input type="text" id="flagin" class="ctfin flagmain" placeholder="0xWR{...}" dir="ltr" '+(solved?'disabled value="'+instanceFlag(mid)+'"':'')+'><button id="flagsub" class="go"'+(solved?' disabled':'')+'>Submit</button></div>'
+'<div id="flagmsg" class="ctfmsg"></div>'
+(solved?'<p>🎉 الفلاج صح! كمّلت التحدي وقدرت تطبّق الموديول كامل عملي.</p><div class="sharerow"><a class="sbtn2" target="_blank" rel="noopener" href="'+shareUrl('whatsapp')+'">📲 واتساب</a><a class="sbtn2" target="_blank" rel="noopener" href="'+shareUrl('linkedin')+'">💼 LinkedIn</a><a class="sbtn2" target="_blank" rel="noopener" href="'+shareUrl('x')+'">✖ X</a><button class="sbtn2" id="copyShareBtn">📋 نسخ النص</button></div><div id="shareMsg" class="ctfmsg"></div>':'');
}

let CTF_TIMER=null;
function ctfInit(mid,CH){
if(CTF_TIMER){clearInterval(CTF_TIMER);CTF_TIMER=null}
const solved=ctfSolved(mid);
const st=P[ctfKey(mid)]=P[ctfKey(mid)]||{};
const launch=$('#launchBtn'),restart=$('#restartBtn'),area=$('#labArea'),help=$('#launchHelp'),tmr=$('#chtimer');

function startFresh(){st.seed=Math.floor(Math.random()*2**31);st.start=Date.now();st.launched=true;save();CF=fragsFromSeed(st.seed)}
function showLaunched(){if(launch)launch.style.display='none';if(restart)restart.style.display='';if(help)help.style.display='none';if(tmr)tmr.style.display='';if(area){area.style.display='';labInit()}}
function startTimer(){const tick=()=>{const left=CH.mins*60000-(Date.now()-st.start);
if(left<=0){startFresh();const out=$('#labout'),msg=$('#flagmsg'),fin=$('#flagin');if(out)out.innerHTML='<div class="labline">⏱ خلصت مدة الـ Instance (30 دقيقة)، اتعمل Reset والفلاج اتغيّر من الأول.</div>';if(fin)fin.value='';if(msg){msg.textContent='⏱ الفلاج القديم بقى ملوش لازمة. استكشف تاني من الأول.';msg.className='ctfmsg bad'}if(tmr)tmr.textContent='⏱ '+fmtMMSS(CH.mins*60000);return}
if(tmr)tmr.textContent='⏱ '+fmtMMSS(left)};
tick();CTF_TIMER=setInterval(tick,1000)}

if(solved){
if(launch)launch.style.display='none';if(restart)restart.style.display='none';if(help)help.style.display='none';if(tmr)tmr.style.display='none';
if(area){area.style.display='';if(st.seed)CF=fragsFromSeed(st.seed);labInit()}
const copyBtn=$('#copyShareBtn');
if(copyBtn)copyBtn.onclick=()=>{const sm=$('#shareMsg');const done=()=>{if(sm){sm.textContent='✓ اتنسخ! الصقه في أي مكان.';sm.className='ctfmsg'}};
if(navigator.clipboard)navigator.clipboard.writeText(shareText()).then(done).catch(done);else done()};
return}

if(st.launched&&st.seed){
if(Date.now()-st.start>CH.mins*60000)startFresh();else CF=fragsFromSeed(st.seed);
showLaunched();startTimer();
}else{
if(restart)restart.style.display='none';if(tmr)tmr.style.display='none';if(area)area.style.display='none';
if(launch){launch.style.display='';launch.onclick=()=>{startFresh();showLaunched();startTimer()}}
}
if(restart)restart.onclick=()=>{startFresh();const out=$('#labout'),fin=$('#flagin'),msg=$('#flagmsg');if(out)out.innerHTML='';if(fin)fin.value='';if(msg){msg.textContent='';msg.className='ctfmsg'}showLaunched();if(CTF_TIMER){clearInterval(CTF_TIMER);CTF_TIMER=null}startTimer()};

const inp=$('#flagin'),btn=$('#flagsub'),msg=$('#flagmsg');
if(!btn||btn.disabled)return;
const go=()=>{const v=(inp.value||'').trim().toLowerCase().replace(/^0xwr\{|\}$/g,'');
const expect=CF.join('_');
if(v===expect){st.solved=true;save();if(CTF_TIMER){clearInterval(CTF_TIMER);CTF_TIMER=null}openPage('ctf_'+mid)}
else{msg.textContent='❌ مش صح. كمّل الاستكشاف وجرّب تاني.';msg.className='ctfmsg bad'}};
btn.onclick=go;inp.onkeydown=e=>{if(e.key==='Enter')go()}}
