function setTheme(t){document.documentElement.dataset.theme=t;try{localStorage.setItem('wo1v-theme2',t)}catch(e){}[['dark','#tdark'],['light','#tlight']].forEach(([k,q])=>{const b=$(q);b.classList.toggle('sel',k===t);b.setAttribute('aria-pressed',k===t)})}
function initTheme(){$('#tdark').innerHTML=MOON;$('#tlight').innerHTML=SUN;let t='light';try{t=localStorage.getItem('wo1v-theme2')==='dark'?'dark':'light'}catch(e){}setTheme(t);$('#tdark').onclick=()=>setTheme('dark');$('#tlight').onclick=()=>setTheme('light')}

/* ---------- البوابة: الآية تشتغل مباشرة ---------- */
function boot(){upd();typeName();route(location.hash.slice(1)||'profile')}
function startGate(){const a=$('#va'),g=$('#gate'),evs=['pointerdown','keydown','touchstart','click'];let fin=false,on=false;
const rm=()=>evs.forEach(x=>document.removeEventListener(x,gest,true));
const end=()=>{if(fin)return;fin=true;rm();try{a.pause()}catch(e){}g.classList.add('out');setTimeout(()=>g.remove(),900);boot()};
const ok=()=>{on=true;rm();$('#eq').classList.add('on');$('#gh').classList.remove('show')};
function gest(e){if(on||fin||(e.target&&e.target.closest&&e.target.closest('#skip')))return;try{a.currentTime=0;const p=a.play();if(p&&p.then)p.then(ok).catch(()=>{});else ok()}catch(x){}}
a.onended=end;a.onerror=end;$('#skip').onclick=end;
try{const p=a.play();if(p&&p.then)p.then(ok).catch(wait);else if(p===undefined&&!a.paused)ok();else wait()}catch(e){wait()}
function wait(){$('#gh').classList.add('show');evs.forEach(x=>document.addEventListener(x,gest,true))}}
/* ---------- تأثيرات الـ scroll والضغط ---------- */
let lastY=0,dir='down',IO;addEventListener('scroll',()=>{const y=scrollY;dir=y>=lastY?'down':'up';lastY=y;requestAnimationFrame(par)},{passive:true});
function par(){const h=$('#hero');if(!h)return;const r=h.getBoundingClientRect();h.style.setProperty('--p',Math.min(1,Math.max(0,-r.top/Math.max(1,r.height))).toFixed(3))}
function reveal(){if(IO)IO.disconnect();if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion:reduce)').matches)return;
IO=new IntersectionObserver(es=>es.forEach(x=>{const t=x.target;if(x.isIntersecting){t.dataset.d=dir;t.classList.add('in')}else t.classList.remove('in')}),{threshold:.1});
$$('#view .card,#view .panel,#view h3,#view h2,#view .note,#view details,#view pre,#view .rm li,#view .qq,#view .vsec,#view .grid>*').forEach(el=>{if(el.parentElement.closest('.card,.panel,.vsec,details,.rvl')||el.closest('.log'))return;el.classList.add('rvl');IO.observe(el)})}
document.addEventListener('pointerdown',e=>{const b=e.target.closest&&e.target.closest('button,.btn,a.sec,summary');if(!b||b.disabled)return;const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height)*2,sp=document.createElement('span');sp.className='rip';sp.style.cssText='width:'+d+'px;height:'+d+'px;left:'+(e.clientX-r.left-d/2)+'px;top:'+(e.clientY-r.top-d/2)+'px';b.appendChild(sp);setTimeout(()=>sp.remove(),650)});
$('#home').onclick=()=>route('profile');initTheme();buildMenu();startGate();
